import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    long x = sc.nextLong();
    int y = sc.nextInt();

    System.out.println((long) Math.max(1, Math.ceil(Math.log10(x / Math.pow(26, y)))));
  }
}

